  function makeTriAuto(type, name = -1, options = {}) {
    let turret = { type: exports.autoTurret, size: 8.5, independent: true };
    if (options.type != null) {
      turret.type = options.type;
    }
    if (options.size != null) {
      turret.size = options.size;
    }
    if (options.independent != null) {
      turret.independent = options.independent;
    }

    let output = JSON.parse(JSON.stringify(type));
    let autogun = [
      {
        //  SIZE               X       Y     ANGLE    ARC
        POSITION: [turret.size, 6, 0, 0, 360, 1],
        TYPE: [
          turret.type,
          {
            CONTROLLERS: ["nearestDifferentMaster"],
            INDEPENDENT: turret.independent,
          },
        ],
      },
      {
        //  SIZE               X       Y     ANGLE    ARC
        POSITION: [turret.size, 6, 0, 120, 360, 1],
        TYPE: [
          turret.type,
          {
            CONTROLLERS: ["nearestDifferentMaster"],
            INDEPENDENT: turret.independent,
          },
        ],
      },
      {
        //  SIZE               X       Y     ANGLE    ARC
        POSITION: [turret.size, 6, 0, 240, 360, 1],
        TYPE: [
          turret.type,
          {
            CONTROLLERS: ["nearestDifferentMaster"],
            INDEPENDENT: turret.independent,
          },
        ],
      },
    ];
    if (type.GUNS != null) {
      output.GUNS = type.GUNS;
    }
    if (type.TURRETS == null) {
      output.TURRETS = autogun;
    } else {
      output.TURRETS = [...type.TURRETS, autogun];
    }
    if (name == -1) {
      output.LABEL = "Triple Auto-" + type.LABEL;
    } else {
      output.LABEL = name;
    }
    output.DANGER = type.DANGER + 1;
    return output;
    if (options.INVISIBLE != null) {
      output.INVISIBLE = options.INVISIBLE;
    }
    return output;
  }
